import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './Adminproduct.css';
import PageTitle from '../PageTitle';
import Sidebar from './Sidebar';

const AdminProduct = () => {
  const [products, setProducts] = useState([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newProduct, setNewProduct] = useState({
    name: '',
    category: 'ana modul',
    price: '',
    productdetails: '',
    image: null
  });

  // API'den ürünleri çekme
  useEffect(() => {
    axios.get('http://localhost:3001/api/products')
      .then(response => setProducts(response.data))
      .catch(error => console.error('Ürünler alınırken hata:', error));
  }, []);

  // Yeni ürün ekleme butonuna tıklandığında modal açılır
  const openModal = () => {
    setIsModalOpen(true);
  };

  // Modal kapatmak için
  const closeModal = () => {
    setIsModalOpen(false);
    setNewProduct({ name: '', category: 'ana modul', price: '', productdetails: '', image: null });
  };

  // Formdaki inputları yönetmek
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setNewProduct(prevState => ({
      ...prevState,
      [name]: value
    }));
  };

  // Fotoğraf seçme
  const handleImageChange = (e) => {
    setNewProduct(prevState => ({
      ...prevState,
      image: e.target.files[0]
    }));
  };

  // Yeni ürünü eklemek için API'ye gönderme
  const handleAddProduct = () => {
    const formData = new FormData();
    formData.append('name', newProduct.name);
    formData.append('category', newProduct.category);
    formData.append('price', newProduct.price);
    formData.append('productdetails', newProduct.productdetails);
    formData.append('image', newProduct.image);

    axios.post('http://localhost:3001/api/products', formData)
      .then(response => {
        setProducts([...products, response.data]);
        closeModal(); // Modal'ı kapat
      })
      .catch(error => {
        console.error('Ürün eklenirken hata:', error);
      });
  };

  return (
    <>
      <PageTitle title="Ürünler" />
      <div className="admin-container">
        <Sidebar />
        <div className="admin-product-container">
          <button className="add-product-button" onClick={openModal}>Yeni Ürün Ekle</button>

          {/* Ürün Tablosu */}
          <table className="admin-product-table">
            <thead>
              <tr>
                <th>Ürün Adı</th>
                <th>Ürün Kategorisi</th>
                <th>Ürün Açıklaması</th>
                <th>Ürün Fiyatı</th>
              </tr>
            </thead>
            <tbody>
              {products.length > 0 ? (
                products.map((product) => (
                  <tr key={product._id}>
                    <td>{product.name}</td>
                    <td>{product.category}</td>
                    <td>{product.productdetails}</td>
                    <td>{product.price} TL</td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="4">Hiç ürün bulunamadı.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Yeni Ürün Modal */}
      {isModalOpen && (
        <div className="modal-overlay">
          <div className="modal-content">
            <h2>Yeni Ürün Ekle</h2>
            <label>Ürün Adı</label>
            <input
              type="text"
              name="name"
              value={newProduct.name}
              onChange={handleInputChange}
            />

            <label>Kategori</label>
            <select
              name="category"
              value={newProduct.category}
              onChange={handleInputChange}
            >
              <option value="ana modul">Ana Modül</option>
              <option value="ek modul">Ek Modül</option>
            </select>

            <label>Fiyat</label>
            <input
              type="number"
              name="price"
              value={newProduct.price}
              onChange={handleInputChange}
            />

            <label>Ürün Detayları</label>
            <textarea
              name="productdetails"
              value={newProduct.productdetails}
              onChange={handleInputChange}
            />

            <label>Fotoğraf Seç</label>
            <input
              type="file"
              name="image"
              onChange={handleImageChange}
            />

            <button onClick={handleAddProduct}>Ürünü Ekle</button>
            <button onClick={closeModal}>İptal</button>
          </div>
        </div>
      )}
    </>
  );
};

export default AdminProduct;
